if (flow.get('dump_active')) return null; // settings download owns the serial port
const lastCmd = flow.get('last_command_time') || 0;
const now = Date.now();
if (now - lastCmd < 2000) return null;
flow.set('last_poll_time', now);
return [
    {payload: {aux: 1, type: 'poll'}},
    {payload: {aux: 2, type: 'poll'}}
];

if (flow.get('dump_active')) { node.warn('Settings download in progress - command ignored'); return null; }

function calculateChecksum(buffer, startIdx, endIdx) {
    let sum = 0;
    for (let i = startIdx; i <= endIdx; i++) sum += buffer[i];
    return (0x100 - (sum & 0xFF)) & 0xFF;
}

function buildReadCommand(aux) {
    const effMap = { 1: 0x02, 2: 0x03 };
    const cmd = Buffer.from([
        0x01, 0x02, 0x00, 0x09, 0x01, 0x50, 0x20, 0x00, 0x00, 0x03, 0x02, effMap[aux], 0x00, 0x00, 0x03
    ]);
    cmd[13] = calculateChecksum(cmd, 2, 12);
    return cmd;
}

function buildWriteCommand(aux, source) {
    const effMap = { 1: 0x02, 2: 0x03 };
    const cmd = Buffer.from([
        0x01, 0x02, 0x00, 0x0B, 0x01, 0x50, 0x20, 0x00, 0x00, 0x03, 0x04, effMap[aux], 0x80, 0x00, source, 0x00, 0x03
    ]);
    cmd[15] = calculateChecksum(cmd, 2, 14);
    return cmd;
}

if (!msg.payload || typeof msg.payload !== 'object') return null;
const { aux, source, type } = msg.payload;

if (type === 'poll') {
    if (![1, 2].includes(aux)) return null;
    return { payload: buildReadCommand(aux) };
}

if (![1, 2].includes(aux) || !(Number.isInteger(source) && source >= 1 && source <= 14)) return null;
return { payload: buildWriteCommand(aux, source) };

// Sony MCS-8M response parser.
// Frames are found by their byte count (BC, big-endian) - never by 0x03, which
// also appears inside frames. Handles poll replies, button replies, and status
// frames the switcher sends ON ITS OWN when something changes on the panel,
// so the dashboard updates immediately instead of at the next poll.
let buf = context.get('buf') || Buffer.alloc(0);
if (Buffer.isBuffer(msg.payload)) buf = Buffer.concat([buf, msg.payload]);
else if (typeof msg.payload === 'string') buf = Buffer.concat([buf, Buffer.from(msg.payload, 'binary')]);

const now = Date.now();
flow.set('last_response_time', now);

const AUX = { 0x02: 1, 0x03: 2 };       // EFF byte -> Aux number
const out = [];

while (buf.length > 0) {
    if (buf[0] === 0x04) { buf = buf.slice(1); continue; }          // audio ACK
    const delIdx = buf.indexOf(0x01);
    if (delIdx === -1) { buf = Buffer.alloc(0); break; }
    if (delIdx > 0) buf = buf.slice(delIdx);
    if (buf.length < 4) break;
    if (buf[1] !== 0x02) { buf = buf.slice(1); continue; }
    const len = (buf[2] << 8) | buf[3];
    if (len < 5 || len > 512) { buf = buf.slice(1); continue; }     // implausible -> resync
    const total = len + 6;
    if (buf.length < total) break;                                  // wait for the rest
    const frame = buf.slice(0, total);
    let sum = 0;
    for (let i = 2; i < total - 1; i++) sum += frame[i];
    if (frame[total - 1] !== 0x03 || (sum & 0xFF) !== 0) { buf = buf.slice(1); continue; }
    buf = buf.slice(total);

    // video frame: [PID=01 ... ] msg = [03, count, EFF, CMD, byte3, byte4]
    const m = frame.slice(9, -2);
    if (frame[4] !== 0x01 || m.length < 6 || m[0] !== 0x03) continue;
    const aux = AUX[m[2]];
    // Only the Aux A-bus (CMD 0x80) is what's actually on the projector.
    // B-bus (0x81) is preset and must NOT drive the LEDs.
    if (!aux || m[3] !== 0x80) continue;
    const source = m[5];

    const sincePoll = now - (flow.get('last_poll_time') || 0);
    const sinceCmd = now - (flow.get('last_command_time') || 0);
    const origin = sinceCmd < 2500 ? 'button reply' : sincePoll < 2500 ? 'poll reply' : 'panel change';
    if (origin === 'panel change') flow.set('push_count', (flow.get('push_count') || 0) + 1);

    out.push({ payload: { aux, source, origin } });
    const t = new Date().toLocaleTimeString();
    node.status({ fill: origin === 'panel change' ? 'blue' : 'green', shape: 'dot',
                  text: `${t} Aux${aux}=${source} (${origin}) | panel pushes: ${flow.get('push_count') || 0}` });
}
context.set('buf', buf);
if (out.length) node.send([out]);
return null;

// Lights the LED next to whichever button matches each Aux output's source,
// and shows the source name. Outputs: Aux1 LEDs 1-4, Aux2 LEDs 1-4, Aux1 name, Aux2 name.
if (!msg.payload || !msg.payload.aux || !msg.payload.source) return null;
flow.set(`aux${msg.payload.aux}_source`, msg.payload.source);
const src = { 1: flow.get('aux1_source') || 0, 2: flow.get('aux2_source') || 0 };
const buttons = flow.get('buttons') || [1, 2, 3, 4];          // set in EDIT SETTINGS HERE
const names = flow.get('source_names') || {};
const name = s => s ? (names[s] || `Input ${s}`) : '-';
const out = [];
for (const aux of [1, 2]) for (let i = 0; i < 4; i++) out.push({ payload: src[aux] === buttons[i] });
out.push({ payload: name(src[1]) }, { payload: name(src[2]) });
return out;

const lastResponse = flow.get('last_response_time') || 0;
const now = Date.now();
if (now - lastResponse > 5000) {
    return { payload: "OFFLINE", color: "red" };
} else {
    return { payload: "ONLINE", color: "green" };
}

// Guard against double-clicks; a stale flag (>5 min) is ignored in case a run died.
const started = flow.get('dump_started') || 0;
if (flow.get('dump_active') && Date.now() - started < 5 * 60 * 1000) {
    return [null, { payload: 'Download already running...' }];
}
flow.set('dump_active', true);
flow.set('dump_started', Date.now());
// Close Node-RED's hold on the serial port so the Python script can use it.
return [{ payload: { enabled: false } }, { payload: 'Releasing serial port...' }];

// Builds the arguments for tools/mcs8m_dump.py from EDIT SETTINGS HERE.
// Dumps are saved in <repo_dir>/dumps/ (ignored by git).
const home = p => String(p).replace(/^~(?=\/|$)/, '$HOME');       // let the shell expand ~
const q = s => '"' + String(s).replace(/["\\`]/g, '') + '"';       // keep paths quoted
const repo = home(flow.get('repo_dir') || '~/mcs8m-protocol').replace(/\/+$/, '');
const port = flow.get('dump_port') || '/dev/ttyUSB0';
const t = new Date(), p = v => String(v).padStart(2, '0');
const ts = `${t.getFullYear()}-${p(t.getMonth() + 1)}-${p(t.getDate())}-${p(t.getHours())}-${p(t.getMinutes())}-${p(t.getSeconds())}`;
msg.payload = `${q(repo + '/tools/mcs8m_dump.py')} -p ${q(port)} -o ${q(repo + '/dumps/mcs8m_settings_' + ts + '.json')}`;
return [msg, { payload: 'Reading switcher settings...' }];

// Receives exec stdout (string, arrives first) and then the return-code object.
if (typeof msg.payload === 'string' || Buffer.isBuffer(msg.payload)) {
    context.set('stdout', String(msg.payload));
    return null;
}
const out = context.get('stdout') || '';
context.set('stdout', '');
flow.set('dump_active', false);

let r = null;
try { r = JSON.parse(out.trim().split('\n').pop()); } catch (e) { }
const rc = msg.payload || {};
let text;
if (r && r.decoded > 0) {
    text = `Saved ${r.decoded}/${r.requests} settings -> ${r.output}`;
} else if (r && r.aborted) {
    text = 'Switcher did not answer - check cable and "Serial Cmd Group = Rem 1"';
} else {
    text = `Download failed (exit ${rc.code}${rc.signal ? ', ' + rc.signal : ''}${rc.message ? ': ' + rc.message : ''})`;
}
// 1: reclaim serial port, 2: status text, 3: toast
return [{ payload: { enabled: true } }, { payload: text }, { payload: text, topic: 'MCS-8M settings download' }];
